// Not minified. The .min.js suffix keeps the personal site's jekyll-terser step from rewriting this ES module.
import { LinkedViewer } from './viewer.min.js';

const $ = (s, r = document) => r.querySelector(s);
const el = (tag, attrs = {}, ...kids) => {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v == null || v === false) continue;
    if (k === 'class') e.className = v; else if (k === 'html') e.innerHTML = v; else if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else e.setAttribute(k, v);
  }
  for (const k of kids.flat()) if (k != null) e.append(k.nodeType ? k : document.createTextNode(k));
  return e;
};
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = v => v.toFixed(1);
const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
// display name of a source: 'DoorCasing' -> 'Door casing', 'customizable-greek-temple' -> 'Greek temple'
const pretty = n => cap(n.replace(/^customizable-/, '').replace(/-/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().trim());

const TYPES = {
  G1: ['Parameter', 'Change one visible attribute (size, proportion, spacing, position, or orientation) of one part or part family.'],
  G2: ['Component', 'Reconstruct the form of one part, together with a size change and one further visible change to it.'],
  G3: ['Multi-component', 'Reconstruct and resize two separate parts independently.'],
  G4: ['Structural', 'Reorganize how three or more regions meet, span, or support one another, changing the overall layout.'],
  S: ['Style', 'Redesign the object in a different style by reshaping its main body and adding four large, mostly geometric cues.'],
  C: ['Composition', 'Place the object in a functional scene with a support surface, three working props, and one large context structure.'],
};
const TYPE_ORDER = ['G1', 'G2', 'G3', 'G4', 'S', 'C'];
const ICON = {
  pass: '<svg class="ic ic-pass" viewBox="0 0 20 20" aria-label="pass" role="img"><circle cx="10" cy="10" r="9" fill="currentColor" opacity=".14"/><path d="M5.8 10.4l2.7 2.7 5.7-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  fail: '<svg class="ic ic-fail" viewBox="0 0 20 20" aria-label="fail" role="img"><circle cx="10" cy="10" r="9" fill="currentColor" opacity=".14"/><path d="M6.6 6.6l6.8 6.8M13.4 6.6l-6.8 6.8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>',
  none: '<svg class="ic ic-none" viewBox="0 0 20 20" aria-label="not run" role="img"><path d="M6 10h8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>',
  crash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l9.5 17h-19z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M12 10v4.5M12 17.2v.3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
};
const verdict = (ok, ran = true) => ran
  ? `<span class="verdict ${ok ? 'pass' : 'fail'}">${ok ? '<svg viewBox="0 0 20 20"><path d="M5 10.5l3 3 7-7.5" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>Pass' : '<svg viewBox="0 0 20 20"><path d="M6 6l8 8M14 6l-8 8" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>Fail'}</span>`
  : '<span class="verdict norun">Did not run</span>';
// thumbnails come from one sprite (assets/img/thumbs.webp, 12 columns, in site.json source order)
let SPRITE = {};
const thumb = id => {
  const i = SPRITE[id] ?? 0, C = 12, R = Math.ceil(Object.keys(SPRITE).length / C);
  return el('span', { class: 'thumb', 'aria-hidden': 'true',
    style: `background-position:${(i % C) / (C - 1) * 100}% ${Math.floor(i / C) / Math.max(R - 1, 1) * 100}%, 0 0;background-size:${C * 100}% ${R * 100}%, 100% 100%` });   // second layer: the pane gradient
};

// Frames for a group of models: one shared frame keeps sizes comparable; a model far larger or smaller than the rest
// (a whole scene around a small object, or a runaway edit) gets its own frame and a visible scale note.
const diag = b => Math.hypot(...b.max.map((v, i) => v - b.min[i]));
const maxDim = bs => { const lo = [0, 1, 2].map(i => Math.min(...bs.map(b => b.min[i]))), hi = [0, 1, 2].map(i => Math.max(...bs.map(b => b.max[i]))); return Math.max(...hi.map((h, i) => h - lo[i])); };
function assignFrames(orig, edits) {   // orig: bounds; edits: [bounds|null] -> {orig: key, edits: [key], note: {key: text}}
  const ds = edits.filter(Boolean).map(diag).sort((a, b) => a - b);
  const med = ds.length ? ds[Math.floor((ds.length - 1) / 2)] : diag(orig);
  const origOwn = diag(orig) < 0.4 * med;
  const ref = origOwn ? med : diag(orig);
  const keys = edits.map((b, i) => !b ? null : (diag(b) > 2.0 * ref || diag(b) < 0.4 * ref) ? 'own' + i : 'shared');
  const shared = [...(origOwn ? [] : [orig]), ...edits.filter((b, i) => b && keys[i] === 'shared')];
  const sharedDim = shared.length ? maxDim(shared) : null;
  const note = b => { if (!sharedDim) return ''; const k = sharedDim / maxDim([b]); return k >= 1 ? `enlarged ${k.toFixed(1)}×` : `shown at ${k.toFixed(2)}× scale`; };
  return { orig: origOwn ? 'own-orig' : 'shared', origNote: origOwn ? note(orig) : '', edits: keys, notes: edits.map((b, i) => b && keys[i] !== 'shared' ? note(b) : '') };
}
const scalePill = t => t ? `<span class="scale">${t}</span>` : '';

let DATA;
fetch('assets/data/site.json?v=1').then(r => r.json()).then(d => {
  DATA = d;
  SPRITE = Object.fromEntries(d.sources.map((s, i) => [s.id, i]));
  initLadder(); initGallery(); initCases(); initLeaderboard();
  initTimeline(); initMultiTurn();
}).catch(e => console.error('site data failed to load', e));
initCopy(); initNav(); initModal();

/* ================================================================ ladder (edit types) */
function initLadder() {
  const src = DATA.ladder_source;
  const tabs = $('#ladder-tabs'), text = $('#ladder-text');
  const container = $('#ladder-viewer');
  const viewer = new LinkedViewer(container, { az: 36, el: 20 });
  container.querySelector('.pane-label .sub').textContent = `armchair, ${src.loc} lines`;
  const panes = [...container.querySelectorAll('.pane-3d')];
  const show = i => {
    const L = DATA.ladder[i];
    [...tabs.children].forEach((t, j) => { t.setAttribute('aria-selected', j === i); t.tabIndex = j === i ? 0 : -1; });
    const [name, def] = TYPES[L.type];
    text.innerHTML = `
      <h3><span class="tbadge" data-t="${L.type}">${L.type}</span> ${name}</h3>
      <p class="tdef">${def}</p>
      <p class="label-sm">Edit instruction</p>
      <div class="instr"><ol>${L.instruction.map((s, j) => `<li class="${j === 0 ? 'pres' : ''}">${esc(cap(s))}</li>`).join('')}</ol></div>
      <p class="label-sm">Checklist · verified from renders</p>
      <ul class="checks">${L.checklist.map((q, j) => `<li>${L.edit.items[j] ? ICON.pass : ICON.fail}<span>${esc(q)}</span></li>`).join('')}</ul>`;
    $('#ladder-edit-label').textContent = L.edit.model;
    $('#ladder-edit-sub').innerHTML = verdict(L.edit.passed, L.edit.ran);
    const fr = assignFrames(src.glb, [L.edit.glb]);
    panes[0].querySelector('.scale')?.remove(); panes[1].querySelector('.scale')?.remove();
    if (fr.origNote) panes[0].querySelector('.pane-label').insertAdjacentHTML('beforeend', scalePill(fr.origNote));
    if (fr.notes[0]) panes[1].querySelector('.pane-label').insertAdjacentHTML('beforeend', scalePill(fr.notes[0]));
    viewer.show([{ el: panes[0], url: src.glb.url, bounds: src.glb, frame: fr.orig },
                 { el: panes[1], url: L.edit.glb && L.edit.glb.url, bounds: L.edit.glb, frame: fr.edits[0] }]);
  };
  DATA.ladder.forEach((L, i) => {
    const t = el('button', { class: 'tab', role: 'tab', type: 'button', style: `--tc: var(--t-${L.type})`, onclick: () => show(i) },
      el('span', { class: 'tbadge', 'data-t': L.type }, L.type), el('span', { class: 'tname' }, TYPES[L.type][0]));
    tabs.append(t);
  });
  tabs.addEventListener('keydown', e => {
    const cur = [...tabs.children].findIndex(t => t.getAttribute('aria-selected') === 'true');
    const n = e.key === 'ArrowRight' ? cur + 1 : e.key === 'ArrowLeft' ? cur - 1 : null;
    if (n == null) return;
    const j = (n + DATA.ladder.length) % DATA.ladder.length; show(j); tabs.children[j].focus();
  });
  show(3);
}

/* ================================================================ gallery + modal */
let modalViewer;
function initModal() {
  const m = $('#modal');
  m.addEventListener('click', e => { if (e.target.closest('[data-close]')) closeModal(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && !m.hidden) closeModal(); });
}
function closeModal() { $('#modal').hidden = true; document.body.style.overflow = ''; }
function openSource(s) {
  const m = $('#modal');
  m.hidden = false; document.body.style.overflow = 'hidden';
  if (!modalViewer) modalViewer = new LinkedViewer($('#modal-viewer'), { az: 36, el: 20 });
  const origin = s.origin === '3DCodeBench' ? '3DCodeBench (procedural, from Infinigen)' : 'Reconstructed from an OpenSCAD design';
  $('#modal-meta').innerHTML = `
    <p class="label-sm" style="margin-top:0">${esc(s.category)}</p>
    <h3 id="modal-title">${esc(pretty(s.name))}</h3>
    ${s.description ? `<p>${esc(s.description)}</p>` : ''}
    <dl>
      <dt>Origin</dt><dd>${esc(origin)}</dd>
      <dt>Program</dt><dd>${s.loc} lines · <a href="https://github.com/BinjieW/3DCodeEdit/blob/main/data/sources/${esc(s.id)}.py">view code</a></dd>
      <dt>Tasks</dt><dd>24 (6 edit types × 4)</dd>
      <dt>License</dt><dd>${esc(s.license)}</dd>
      ${s.author ? `<dt>Author</dt><dd>${esc(s.author)}</dd>` : ''}
      <dt>Upstream</dt><dd><a href="${esc(s.upstream)}">source page</a></dd>
      <dt>ID</dt><dd><code>${esc(s.id)}</code></dd>
    </dl>`;
  const pane = $('#modal-viewer .pane-3d');
  pane.querySelector('.pane-msg')?.remove();
  if (s.glb) modalViewer.show([{ el: pane, url: s.glb.url, bounds: s.glb, frame: 'shared' }]);
  else { modalViewer.show([]); pane.append(el('div', { class: 'pane-msg', html: '3D preview unavailable' })); }
  setTimeout(() => modalViewer.resize(), 30);
  $('.modal-close').focus();
}
function initGallery() {
  const cats = {};
  for (const s of DATA.sources) cats[s.category] = (cats[s.category] || 0) + 1;
  const order = Object.keys(cats).sort((a, b) => cats[b] - cats[a]);
  const filt = $('#gallery-filter'), grid = $('#gallery'), more = $('#gallery-more');
  let active = 'All', expanded = false;
  // interleave categories so the first rows show the variety of the benchmark
  const byCat = {};
  for (const s of DATA.sources) (byCat[s.category] ||= []).push(s);
  Object.values(byCat).forEach(l => l.sort((a, b) => pretty(a.name).localeCompare(pretty(b.name))));
  const mixed = [];
  for (let i = 0; mixed.length < DATA.sources.length; i++) for (const c of order) if (byCat[c][i]) mixed.push(byCat[c][i]);
  const perRow = () => Math.max(1, Math.round(grid.clientWidth / 130));
  const draw = () => {
    grid.innerHTML = '';
    const list = active === 'All' ? mixed : byCat[active];
    const limit = expanded ? list.length : perRow() * 3;
    for (const s of list.slice(0, limit)) {
      grid.append(el('button', { class: 'gitem', type: 'button', title: `${pretty(s.name)} · ${s.category}`, onclick: () => openSource(s) },
        thumb(s.id), el('span', { class: 'gname' }, pretty(s.name))));
    }
    more.hidden = list.length <= limit && !expanded;
    more.textContent = expanded ? 'Show fewer' : `Show all ${list.length} programs`;
    [...filt.children].forEach(c => c.setAttribute('aria-pressed', c.dataset.v === active));
  };
  more.addEventListener('click', () => { expanded = !expanded; draw(); if (!expanded) grid.scrollIntoView({ block: 'nearest' }); });
  let lastPer = 0;
  new ResizeObserver(() => { const p = perRow(); if (p !== lastPer) { lastPer = p; draw(); } }).observe(grid);
  for (const c of ['All', ...order]) {
    filt.append(el('button', { class: 'chip', type: 'button', 'data-v': c, onclick: () => { active = c; expanded = false; draw(); } },
      c, el('span', { class: 'n' }, String(c === 'All' ? DATA.sources.length : cats[c]))));
  }
  draw();
}

/* ================================================================ examples */
function initCases() {
  const list = $('#case-list'), filt = $('#case-filter');
  const container = $('#case-viewer');
  const viewer = new LinkedViewer(container, { az: 36, el: 22, autoRotate: false });
  let active = 'All', current = null;
  const counts = {};
  for (const c of DATA.cases) counts[c.type] = (counts[c.type] || 0) + 1;
  const drawList = () => {
    list.innerHTML = '';
    for (const c of DATA.cases.filter(c => active === 'All' || c.type === active)) {
      list.append(el('button', { class: 'case-btn', type: 'button', role: 'option', 'aria-selected': c === current, onclick: () => show(c) },
        thumb(c.source),
        el('span', { class: 'tbadge', 'data-t': c.type }, c.type), c.title));
    }
    [...filt.children].forEach(b => b.setAttribute('aria-pressed', b.dataset.v === active));
  };
  for (const t of ['All', ...TYPE_ORDER.filter(t => counts[t])]) {
    filt.append(el('button', { class: 'chip', type: 'button', 'data-v': t, onclick: () => {
      active = t; if (t !== 'All' && current.type !== t) current = DATA.cases.find(c => c.type === t); drawList(); show(current);
    } }, t === 'All' ? 'All types' : `${t} · ${TYPES[t][0]}`, el('span', { class: 'n' }, String(t === 'All' ? DATA.cases.length : counts[t]))));
  }
  const show = c => {
    current = c;
    [...list.children].forEach(b => b.setAttribute('aria-selected', b.textContent.endsWith(c.title)));
    const src = DATA.sources.find(s => s.id === c.source);
    $('#case-head').innerHTML = `
      <div class="case-title"><span class="tbadge" data-t="${c.type}">${c.type}</span><h3>${esc(c.title)}</h3></div>
      <div class="case-src">${esc(TYPES[c.type][0])} edit · source: ${esc(pretty(c.source_name).toLowerCase())} (${src.origin === '3DCodeBench' ? '3DCodeBench' : 'OpenSCAD'}, ${c.src_loc} lines)</div>
      <div class="instr"><ol>${c.instruction.map((s, j) => `<li class="${j === 0 ? 'pres' : ''}">${esc(cap(s))}</li>`).join('')}</ol></div>`;
    container.querySelectorAll('.pane-3d').forEach(p => p.remove());
    const fr = assignFrames(c.original, c.edits.map(e => e.glb));
    const panes = [];
    const orig = el('div', { class: 'pane-3d orig' }, el('div', { class: 'pane-label', html: `<b>Original</b><span class="sub">${c.src_loc} lines</span>${scalePill(fr.origNote)}` }));
    container.append(orig); panes.push({ el: orig, url: c.original.url, bounds: c.original, frame: fr.orig });
    c.edits.forEach((e, i) => {
      const p = el('div', { class: 'pane-3d' }, el('div', { class: 'pane-label', html: `<b>${esc(e.model)}</b>${verdict(e.passed, e.ran)}${e.note ? `<span class="fnote">${esc(e.note)}</span>` : ''}${scalePill(fr.notes[i])}` }));
      if (!e.ran) p.append(el('div', { class: 'pane-msg', html: `${ICON.crash}<span>The edited program failed to run or render, so the task fails.</span>` }));
      else if (!e.glb) p.append(el('div', { class: 'pane-msg', html: '3D preview unavailable' }));
      container.append(p); panes.push({ el: p, url: e.glb && e.glb.url, bounds: e.glb, frame: fr.edits[i] });
    });
    viewer.show(panes);
    // checklist matrix
    const head = `<thead><tr><th scope="col">Checklist item</th>${c.edits.map(e => `<th scope="col">${esc(e.model).replace(/-/g, '\u2011')}</th>`).join('')}</tr></thead>`;
    const rows = c.checklist.map((q, i) => `<tr class="${i === 0 ? 'pres' : ''}"><td class="q"><span class="num">${i}</span>${esc(q)}</td>${
      c.edits.map(e => `<td>${!e.ran ? ICON.none : e.items[i] ? ICON.pass : ICON.fail}</td>`).join('')}</tr>`).join('');
    const foot = `<tfoot><tr><td class="q">Task (all items pass)</td>${c.edits.map(e => `<td>${verdict(e.passed, e.ran)}</td>`).join('')}</tr></tfoot>`;
    $('#case-matrix').innerHTML = head + `<tbody>${rows}</tbody>` + foot;
  };
  current = DATA.cases.find(c => c.id.includes('miniature-brick-lumber-house_L5_Q1')) || DATA.cases[0];
  drawList(); show(current);
}

/* ================================================================ leaderboard */
function initLeaderboard() {
  const t = $('#lb'), small = $('#lb-small');
  const cols = [['all', 'All'], ['G1', 'G1'], ['G2', 'G2'], ['G3', 'G3'], ['G4', 'G4'], ['S', 'S'], ['C', 'C'], ['exec', 'Exec.']];
  const SEP = new Set(['all', 'G1', 'S', 'exec']);
  let sortKey = 'all', dir = -1;
  const draw = () => {
    const shown = DATA.leaderboard.filter(r => r.main || small.checked);
    const rows = shown.slice().sort((a, b) => sortKey === 'model' ? dir * a.model.localeCompare(b.model) : dir * (a[sortKey] - b[sortKey]) || a.model.localeCompare(b.model));
    const best = {}, avg = {};
    for (const [k] of cols) { best[k] = Math.max(...rows.map(r => r[k])); avg[k] = shown.reduce((s, r) => s + r[k], 0) / shown.length; }
    if (!small.checked && DATA.average17) Object.assign(avg, DATA.average17);   // the paper's Average row (computed from unrounded rates)
    const cls = (k, extra = '') => [SEP.has(k) ? 'sep' : '', extra].filter(Boolean).join(' ');
    const th = (k, label, extra = '') => `<th scope="col" class="${cls(k, extra)}" data-k="${k}" ${sortKey === k ? `aria-sort="${dir < 0 ? 'descending' : 'ascending'}"` : ''}>${label}</th>`;
    const cell = (r, k) => k === 'all'
      ? `<td class="${cls(k, 'allcell' + (r[k] === best[k] ? ' best' : ''))}"><div class="allbar"><div class="track"><div class="fill" style="width:${r[k]}%;background:var(${r.open ? '--open' : '--closed'})"></div></div><b>${fmt(r[k])}</b></div></td>`
      : `<td class="${cls(k, r[k] === best[k] ? 'best' : '')}">${fmt(r[k])}</td>`;
    t.innerHTML = `<thead>
      <tr class="grp"><th class="rank"></th><th class="mname"></th><th class="sep"></th><th class="sep" colspan="4" style="text-align:center">Geometric</th><th class="sep" colspan="2" style="text-align:center">Open-ended</th><th class="sep"></th></tr>
      <tr><th scope="col" class="rank">#</th>${th('model', 'Model', 'mname')}${cols.map(([k, l]) => th(k, l, k === 'all' ? 'allhead' : '')).join('')}</tr></thead>
      <tbody>${rows.map((r, i) => `<tr><td class="rank">${i + 1}</td><td class="mname">${esc(r.model)}${r.open ? '<span class="ow">open</span>' : ''}</td>${cols.map(([k]) => cell(r, k)).join('')}</tr>`).join('')}
      <tr class="avg"><td class="rank"></td><td class="mname">Average (${shown.length} models)</td>${cols.map(([k]) => `<td class="${cls(k)}">${fmt(avg[k])}</td>`).join('')}</tr>
      </tbody>`;
    t.querySelectorAll('thead th[data-k]').forEach(h => h.addEventListener('click', () => {
      const k = h.dataset.k; if (k === sortKey) dir = -dir; else { sortKey = k; dir = k === 'model' ? 1 : -1; } draw();
    }));
  };
  small.addEventListener('change', draw);
  draw();
}

/* ================================================================ chart helpers */
const NS = 'http://www.w3.org/2000/svg';
const svgEl = (tag, attrs = {}) => { const e = document.createElementNS(NS, tag); for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v); return e; };
function responsive(node, draw) {
  let w = 0;
  const ro = new ResizeObserver(() => { const nw = Math.round(node.clientWidth); if (nw && nw !== w) { w = nw; draw(w); } });
  ro.observe(node);
}
function tooltip(node) {
  const tt = el('div', { class: 'tooltip', role: 'status' }); node.append(tt);
  return {
    show(html, x, y) {
      tt.innerHTML = html; tt.classList.add('on');
      const W = node.clientWidth, tw = tt.offsetWidth, th = tt.offsetHeight;
      let left = x + 14; if (left + tw > W) left = x - tw - 14; if (left < 0) left = Math.max(0, W - tw);
      let top = y - th - 10; if (top < 0) top = y + 14;
      tt.style.left = left + 'px'; tt.style.top = top + 'px';
    },
    hide() { tt.classList.remove('on'); },
  };
}
const ink = '#171e27', ink2 = '#4a5260', ink3 = '#737a86', grid = '#eceef1';

/* ================================================================ timeline */
const FAM = [
  ['GPT flagship', 'GPT', '#2a78d6'],
  ['Claude Opus', 'Claude Opus', '#eb6834'],
  ['Gemini Flash', 'Gemini Flash', '#1baf7a'],
  ['Qwen ~27-32B', 'Qwen (27–32B)', '#4a3aa7'],
];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dateLabel = s => { const [y, m, d] = s.split('-').map(Number); return `${MONTHS[m - 1]} ${d}, ${y}`; };
function initTimeline() {
  const node = $('#chart-timeline');
  const pts = DATA.timeline.map(p => ({ ...p, t: Date.parse(p.release) })).sort((a, b) => a.t - b.t);
  const tip = tooltip(node);
  responsive(node, W => {
    node.querySelector('svg')?.remove();
    const H = W < 560 ? 300 : 340;
    const m = { l: 40, r: W < 560 ? 92 : 112, t: 14, b: 30 };
    const x0 = Date.parse('2024-10-15'), x1 = Date.parse('2026-10-25');
    const X = t => m.l + (t - x0) / (x1 - x0) * (W - m.l - m.r);
    const Y = v => m.t + (1 - v / 80) * (H - m.t - m.b);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': 'All-pass rate of 44 models by release date' });
    const g = svgEl('g', { class: 'grid' }); svg.append(g);
    for (const v of [0, 20, 40, 60, 80]) {
      g.append(svgEl('line', { x1: m.l, x2: W - m.r + 6, y1: Y(v), y2: Y(v) }));
      const tx = svgEl('text', { x: m.l - 8, y: Y(v) + 4, 'text-anchor': 'end', class: 'tick' }); tx.textContent = v + '%';
      const tg = svgEl('g', { class: 'tick' }); tg.append(tx); svg.append(tg);
    }
    const xt = W < 560 ? [['2025', '2025-01-01'], ['2026', '2026-01-01']] : [['Jan 2025', '2025-01-01'], ['Jul 2025', '2025-07-01'], ['Jan 2026', '2026-01-01'], ['Jul 2026', '2026-07-01']];
    for (const [lab, iso] of xt) {
      const tg = svgEl('g', { class: 'tick' });
      const tx = svgEl('text', { x: X(Date.parse(iso)), y: H - 8, 'text-anchor': 'middle' }); tx.textContent = lab; tg.append(tx); svg.append(tg);
      svg.append(svgEl('line', { x1: X(Date.parse(iso)), x2: X(Date.parse(iso)), y1: H - m.b, y2: H - m.b + 4, stroke: '#d3d6dc' }));
    }
    svg.append(svgEl('line', { x1: m.l, x2: W - m.r + 6, y1: Y(0), y2: Y(0), stroke: '#d3d6dc' }));
    // April 2026 marker
    const xa = X(Date.parse('2026-04-01'));
    svg.append(svgEl('line', { x1: xa, x2: xa, y1: m.t, y2: H - m.b, stroke: '#d9d4c6', 'stroke-width': 1 }));
    const at = svgEl('text', { x: xa + 4, y: m.t + 10, class: 'lbl', style: 'font-size:11px;fill:#8a8577' }); at.textContent = 'Apr 2026'; svg.append(at);
    // grey dots for other models
    const fams = new Set(FAM.map(f => f[0]));
    const marks = [];
    for (const p of pts) if (!fams.has(p.family)) {
      const c = svgEl('circle', { cx: X(p.t), cy: Y(p.all), r: 3.5, fill: '#c3c6cc', stroke: '#fff', 'stroke-width': 1.5 }); svg.append(c); marks.push([p, c, '#9aa0a8']);
    }
    // best so far (step)
    let best = -1, d = '';
    for (const p of pts) { if (p.all > best) { d += d ? ` H${X(p.t)} V${Y(p.all)}` : `M${X(p.t)} ${Y(p.all)}`; best = p.all; } }
    d += ` H${X(Date.parse('2026-10-20'))}`;
    svg.append(svgEl('path', { d, fill: 'none', stroke: ink, 'stroke-width': 1.5, 'stroke-dasharray': '4 3', opacity: .75 }));
    // family lines
    const ends = [];
    for (const [fam, lab, col] of FAM) {
      const fp = pts.filter(p => p.family === fam);
      svg.append(svgEl('path', { d: fp.map((p, i) => `${i ? 'L' : 'M'}${X(p.t)} ${Y(p.all)}`).join(' '), fill: 'none', stroke: col, 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));
      for (const p of fp) { const c = svgEl('circle', { cx: X(p.t), cy: Y(p.all), r: 4, fill: col, stroke: '#fff', 'stroke-width': 2 }); svg.append(c); marks.push([p, c, col]); }
      const last = fp[fp.length - 1];
      ends.push({ lab, col, x: X(last.t), y: Y(last.all) });
    }
    // end labels in a column right of the data, spread so they never overlap, with leader lines
    ends.sort((a, b) => a.y - b.y);
    const gap = 16, lx = W - m.r + 14;
    const ys = ends.map(e => e.y);
    for (let it = 0; it < 50; it++) for (let i = 1; i < ys.length; i++) if (ys[i] - ys[i - 1] < gap) { const mid = (ys[i] + ys[i - 1]) / 2; ys[i - 1] = mid - gap / 2; ys[i] = mid + gap / 2; }
    ends.forEach((e, i) => {
      svg.append(svgEl('path', { d: `M${e.x + 6} ${e.y} L${lx - 4} ${ys[i]}`, stroke: '#c3c6cc', 'stroke-width': 1, fill: 'none' }));
      svg.append(svgEl('circle', { cx: lx + 1, cy: ys[i], r: 3.5, fill: e.col }));
      const t = svgEl('text', { x: lx + 8, y: ys[i] + 4, class: 'lbl', style: 'font-size:12px;fill:#171e27' }); t.textContent = e.lab; svg.append(t);
    });
    // legend for grey dots + frontier (inside plot, top-left)
    const lg = svgEl('g', { transform: `translate(${m.l + 10},${m.t + 8})` });
    lg.append(svgEl('circle', { cx: 4, cy: 0, r: 3.5, fill: '#c3c6cc' }));
    const t1 = svgEl('text', { x: 14, y: 4, class: 'lbl' }); t1.textContent = 'other models'; lg.append(t1);
    lg.append(svgEl('path', { d: 'M-2 18 H10', stroke: ink, 'stroke-width': 1.5, 'stroke-dasharray': '4 3' }));
    const t2 = svgEl('text', { x: 14, y: 22, class: 'lbl' }); t2.textContent = 'best so far'; lg.append(t2);
    svg.append(lg);
    // hover: nearest mark
    const ring = svgEl('circle', { r: 7, fill: 'none', stroke: ink, 'stroke-width': 1.5, opacity: 0 }); svg.append(ring);
    const hit = svgEl('rect', { x: m.l, y: m.t, width: W - m.l - m.r, height: H - m.t - m.b, fill: 'transparent' }); svg.append(hit);
    const move = ev => {
      const r = svg.getBoundingClientRect(), sx = W / r.width;
      const mx = (ev.clientX - r.left) * sx, my = (ev.clientY - r.top) * sx;
      let bestD = 1e9, bm = null;
      for (const mk of marks) { const dx = +mk[1].getAttribute('cx') - mx, dy = +mk[1].getAttribute('cy') - my, dd = dx * dx + dy * dy; if (dd < bestD) { bestD = dd; bm = mk; } }
      if (!bm || bestD > 30 * 30) { ring.setAttribute('opacity', 0); tip.hide(); return; }
      const [p, c, col] = bm;
      ring.setAttribute('cx', c.getAttribute('cx')); ring.setAttribute('cy', c.getAttribute('cy')); ring.setAttribute('opacity', 1);
      tip.show(`<div class="tt-h">${esc(p.model)}</div><div class="tt-s">Released ${dateLabel(p.release)}</div>
        <div class="tt-row"><i class="sw" style="background:${col}"></i>All-pass ${fmt(p.all)}%</div>
        <div class="tt-s">G4 ${fmt(p.G4)} · S ${fmt(p.S)} · C ${fmt(p.C)}</div>`, (+c.getAttribute('cx')) / sx, (+c.getAttribute('cy')) / sx);
    };
    hit.addEventListener('pointermove', move); hit.addEventListener('pointerleave', () => { ring.setAttribute('opacity', 0); tip.hide(); });
    node.prepend(svg);
  });
  // panel (b): best per edit type before April 2026 vs all models
  const node2 = $('#chart-types');
  const cut = Date.parse('2026-04-01');
  const rows = TYPE_ORDER.map(t => {
    const before = Math.max(...pts.filter(p => p.t < cut).map(p => p[t])), all = Math.max(...pts.map(p => p[t]));
    return { t, before, all, bm: pts.filter(p => p.t < cut).find(p => p[t] === before).model, am: pts.find(p => p[t] === all).model };
  });
  const tip2 = tooltip(node2);
  responsive(node2, W => {
    node2.querySelector('svg')?.remove();
    const rh = 40, m = { l: 36, r: 44, t: 8, b: 30 }, H = m.t + m.b + rh * rows.length;
    const X = v => m.l + v / 100 * (W - m.l - m.r);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': 'Best all-pass rate per edit type before April 2026 and among all models' });
    for (const v of [0, 25, 50, 75, 100]) {
      svg.append(svgEl('line', { x1: X(v), x2: X(v), y1: m.t, y2: H - m.b, stroke: grid }));
      const t = svgEl('text', { x: X(v), y: H - 10, 'text-anchor': 'middle', style: `font-size:11.5px;fill:${ink3}` }); t.textContent = v + '%'; svg.append(t);
    }
    rows.forEach((r, i) => {
      const y = m.t + rh * i + rh / 2;
      const lab = svgEl('text', { x: m.l - 10, y: y + 4, 'text-anchor': 'end', style: `font-size:12.5px;font-weight:600;fill:${ink}` }); lab.textContent = r.t; svg.append(lab);
      svg.append(svgEl('line', { x1: X(r.before), x2: X(r.all), y1: y, y2: y, stroke: '#c3c6cc', 'stroke-width': 3, 'stroke-linecap': 'round' }));
      svg.append(svgEl('circle', { cx: X(r.before), cy: y, r: 5, fill: '#fff', stroke: ink, 'stroke-width': 1.6 }));
      svg.append(svgEl('circle', { cx: X(r.all), cy: y, r: 5, fill: ink, stroke: '#fff', 'stroke-width': 2 }));
      const d = svgEl('text', { x: X(r.all) + 10, y: y + 4, style: `font-size:12px;fill:${ink2}` }); d.textContent = `+${Math.round(r.all - r.before)}`; svg.append(d);
      const hit = svgEl('rect', { x: 0, y: y - rh / 2, width: W, height: rh, fill: 'transparent' }); svg.append(hit);
      hit.addEventListener('pointermove', ev => {
        const b = svg.getBoundingClientRect();
        tip2.show(`<div class="tt-h">${r.t} · ${TYPES[r.t][0]}</div><div>Before Apr 2026: ${fmt(r.before)}% <span class="tt-s">(${esc(r.bm)})</span></div><div>All models: ${fmt(r.all)}% <span class="tt-s">(${esc(r.am)})</span></div>`,
          ev.clientX - b.left, ev.clientY - b.top);
      });
      hit.addEventListener('pointerleave', () => tip2.hide());
    });
    node2.prepend(svg);
  });
  const lg = el('div', { class: 'chart-legend', html: `<span><svg width="12" height="12"><circle cx="6" cy="6" r="4.5" fill="#fff" stroke="${ink}" stroke-width="1.5"/></svg>Before Apr 2026</span><span><svg width="12" height="12"><circle cx="6" cy="6" r="5" fill="${ink}"/></svg>All models</span>` });
  node2.after(lg);
}

/* ================================================================ multi-turn (four findings as tabs) */
// Analysis subset, 312 tasks; numbers from the paper's Tables (mt_main, mt_rounds, mt_agent). null: not available.
const MT = { // editor: [single-shot, self-check code, self-check renders, reviewer P/F, reviewer full, self-review]
  'GPT-6.1-sol': [64.7, 71.5, 76.0, 75.6, 85.6, 83.0], 'Claude Opus 5.5': [67.6, 68.3, 74.0, 81.7, 83.0, 83.3],
  'Claude Sonnet 5.5': [50.6, 55.1, 55.4, 67.3, 71.2, 69.9], 'GPT-6-luna': [36.9, 42.6, 49.7, 59.0, 65.7, 61.5],
  'Qwen3.8-27B': [26.0, 31.4, 33.0, 43.6, 50.3, 37.2], 'Qwen3-VL-235B': [11.9, 10.9, 12.5, 14.4, 16.7, 13.1],
  'gpt-oss-120b': [14.4, 15.4, null, 17.9, 22.8, 15.1], 'Qwen3-Coder-Next': [8.7, 10.6, null, 13.1, 13.5, 10.6],
};
const ROUNDS = { // mean revisions: self-check renders (code for text-only), reviewer full
  'GPT-6.1-sol': [0.3, 2.8], 'Claude Opus 5.5': [0.5, 2.7], 'Claude Sonnet 5.5': [0.6, 3.8], 'GPT-6-luna': [2.7, 3.2],
  'Qwen3.8-27B': [1.6, 5.0], 'Qwen3-VL-235B': [2.1, 6.9], 'gpt-oss-120b': [1.6, 6.5], 'Qwen3-Coder-Next': [4.6, 7.0],
};
const C_SINGLE = 'hollow', C_CODE = '#9aa6b6', C_REND = '#1baf7a', C_PF = '#86b6ef', C_FULL = '#2a78d6', C_SELF = '#eb6834';
// Generic dot-row chart: one row per label, markers per series on a shared 0..xmax scale, a thin bar from the
// smallest to the largest marker, and a value label after the series flagged `label`.
function dotRows(node, { rows, series, xmax = 90, ref, legend }) {
  const tip = tooltip(node);
  responsive(node, W => {
    node.querySelector('svg')?.remove();
    const narrow = W < 560;
    const rh = 34, m = { l: narrow ? 118 : 140, r: 44, t: ref ? 22 : 6, b: 28 }, H = m.t + m.b + rh * rows.length;
    const X = v => m.l + v / xmax * (W - m.l - m.r);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img' });
    for (let v = 0; v <= xmax; v += xmax > 60 ? 30 : 20) {
      svg.append(svgEl('line', { x1: X(v), x2: X(v), y1: m.t, y2: H - m.b, stroke: grid }));
      const t = svgEl('text', { x: X(v), y: H - 8, 'text-anchor': 'middle', style: `font-size:11.5px;fill:${ink3}` }); t.textContent = v + '%'; svg.append(t);
    }
    if (ref) {
      svg.append(svgEl('line', { x1: X(ref.v), x2: X(ref.v), y1: m.t - 6, y2: H - m.b, stroke: '#8a8577', 'stroke-width': 1.2, 'stroke-dasharray': '4 3' }));
      const t = svgEl('text', { x: X(ref.v), y: 12, 'text-anchor': 'middle', style: 'font-size:11.5px;fill:#6f6a5c' }); t.textContent = ref.label; svg.append(t);
    }
    rows.forEach((r, i) => {
      const y = m.t + rh * i + rh / 2;
      const lab = svgEl('text', { x: m.l - 12, y: y + 4, 'text-anchor': 'end', style: `font-size:12.5px;fill:${ink}${r.strong ? ';font-weight:600' : ''}` }); lab.textContent = r.label; svg.append(lab);
      const vals = series.map(s => r.v[s.i]).filter(v => v != null);
      if (!vals.length) return;
      svg.append(svgEl('line', { x1: X(Math.min(...vals)), x2: X(Math.max(...vals)), y1: y, y2: y, stroke: '#d3d6dc', 'stroke-width': 3, 'stroke-linecap': 'round' }));
      series.forEach(s => {
        const v = r.v[s.i]; if (v == null) return;
        if (s.color === C_SINGLE) svg.append(svgEl('circle', { cx: X(v), cy: y, r: 4.5, fill: '#fff', stroke: ink, 'stroke-width': 1.6 }));
        else svg.append(svgEl('circle', { cx: X(v), cy: y, r: s.label ? 5.5 : 4.5, fill: s.color, stroke: '#fff', 'stroke-width': 2 }));
      });
      const ls = series.find(s => s.label), lv = ls && r.v[ls.i];
      if (lv != null) { const t = svgEl('text', { x: X(Math.max(...vals)) + 9, y: y + 4, style: `font-size:12px;font-weight:600;fill:${ink}` }); t.textContent = fmt(lv); svg.append(t); }
      const hit = svgEl('rect', { x: 0, y: y - rh / 2, width: W, height: rh, fill: 'transparent' }); svg.append(hit);
      hit.addEventListener('pointermove', ev => {
        const b = svg.getBoundingClientRect();
        tip.show(`<div class="tt-h">${esc(r.label)}</div>` + series.map(s => `<div class="tt-row"><i class="sw" style="background:${s.color === C_SINGLE ? '#fff;border:1.5px solid ' + ink : s.color}"></i>${s.name}: ${r.v[s.i] == null ? '–' : fmt(r.v[s.i]) + '%'}</div>`).join(''), ev.clientX - b.left, ev.clientY - b.top);
      });
      hit.addEventListener('pointerleave', () => tip.hide());
    });
    node.prepend(svg);
  });
  node.after(el('div', { class: 'chart-legend', html: (legend || series).map(s => `<span><svg width="12" height="12">${s.color === C_SINGLE ? `<circle cx="6" cy="6" r="4.5" fill="#fff" stroke="${ink}" stroke-width="1.5"/>` : `<circle cx="6" cy="6" r="5" fill="${s.color}"/>`}</svg>${s.name}</span>`).join('') }));
}
// Grouped horizontal bars: groups of settings, one bar per editor.
function groupBars(node, { groups, editors, xmax = 100 }) {
  const tip = tooltip(node);
  responsive(node, W => {
    node.querySelector('svg')?.remove();
    const bh = 11, gap = 3, gh = 22 + editors.length * (bh + gap) + 10, m = { l: 4, r: 44, t: 4, b: 4 }, H = m.t + m.b + gh * groups.length;
    const X = v => m.l + v / xmax * (W - m.l - m.r);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img' });
    groups.forEach((g, i) => {
      const y0 = m.t + gh * i;
      const t = svgEl('text', { x: m.l, y: y0 + 15, style: `font-size:12.5px;fill:${ink}${g.fb ? ';font-weight:600' : ''}` }); t.textContent = g.label; svg.append(t);
      editors.forEach((e, j) => {
        const v = g.v[j], y = y0 + 22 + j * (bh + gap);
        svg.append(svgEl('rect', { x: X(0), y, width: X(xmax) - X(0), height: bh, fill: '#f1f2f4', rx: 2 }));
        svg.append(svgEl('path', { d: `M${X(0)} ${y} H${X(v) - 3} a3 3 0 0 1 3 3 V${y + bh - 3} a3 3 0 0 1 -3 3 H${X(0)} Z`, fill: g.fb ? e.color : e.muted }));
        const vt = svgEl('text', { x: X(v) + 6, y: y + bh - 1.5, style: `font-size:11.5px;font-weight:600;fill:${ink}` }); vt.textContent = fmt(v); svg.append(vt);
        const hit = svgEl('rect', { x: 0, y, width: W, height: bh + gap, fill: 'transparent' }); svg.append(hit);
        hit.addEventListener('pointermove', ev => { const b = svg.getBoundingClientRect(); tip.show(`<div class="tt-h">${esc(e.name)}</div><div>${esc(g.label)}: ${fmt(v)}%</div>`, ev.clientX - b.left, ev.clientY - b.top); });
        hit.addEventListener('pointerleave', () => tip.hide());
      });
    });
    node.prepend(svg);
  });
  node.after(el('div', { class: 'chart-legend', html: editors.map(e => `<span><i class="sw" style="background:${e.color}"></i>${e.name}</span>`).join('') + `<span><i class="sw" style="background:#c9ced6"></i>lighter bars: more compute, no feedback</span>` }));
}
function initMultiTurn() {
  const R = (names, strong = []) => names.map(n => ({ label: n, v: MT[n], strong: strong.includes(n) }));
  const VISION = ['GPT-6.1-sol', 'Claude Opus 5.5', 'Claude Sonnet 5.5', 'GPT-6-luna', 'Qwen3.8-27B', 'Qwen3-VL-235B'];
  dotRows($('#mt-c1'), { rows: R(VISION), xmax: 90, series: [
    { i: 0, name: 'Single-shot', color: C_SINGLE }, { i: 1, name: 'Self-check, rereading its code', color: C_CODE },
    { i: 2, name: 'Self-check, seeing its renders', color: C_REND, label: true }] });
  dotRows($('#mt-c2'), { rows: R(Object.keys(MT)).map(r => ({ ...r, v: [r.v[2] ?? r.v[1], r.v[3], r.v[4]] })), xmax: 90, series: [
    { i: 0, name: 'Self-check (renders; code for text-only editors)', color: C_REND }, { i: 1, name: 'Reviewer: which requirements fail', color: C_PF },
    { i: 2, name: 'Reviewer: how the renders differ', color: C_FULL, label: true }] });
  // revision rounds: two short bars per editor
  const node = $('#mt-c2b'), tip = tooltip(node), names = Object.keys(ROUNDS);
  responsive(node, W => {
    node.querySelector('svg')?.remove();
    const rh = 34, m = { l: W < 400 ? 112 : 124, r: 30, t: 6, b: 28 }, H = m.t + m.b + rh * names.length, X = v => m.l + v / 8 * (W - m.l - m.r);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img' });
    for (const v of [0, 2, 4, 6, 8]) {
      svg.append(svgEl('line', { x1: X(v), x2: X(v), y1: m.t, y2: H - m.b, stroke: grid }));
      const t = svgEl('text', { x: X(v), y: H - 8, 'text-anchor': 'middle', style: `font-size:11.5px;fill:${ink3}` }); t.textContent = v; svg.append(t);
    }
    names.forEach((n, i) => {
      const y = m.t + rh * i + 6, [a, b] = ROUNDS[n];
      const lab = svgEl('text', { x: m.l - 10, y: y + 15, 'text-anchor': 'end', style: `font-size:12px;fill:${ink}` }); lab.textContent = n; svg.append(lab);
      [[a, C_REND, 0], [b, C_FULL, 11]].forEach(([v, c, dy]) => {
        svg.append(svgEl('rect', { x: X(0), y: y + dy, width: Math.max(1.5, X(v) - X(0)), height: 9, fill: c, rx: 2 }));
        const t = svgEl('text', { x: X(v) + 4, y: y + dy + 8.5, style: `font-size:10.5px;fill:${ink2}` }); t.textContent = v.toFixed(1); svg.append(t);
      });
    });
    node.prepend(svg);
  });
  node.after(el('div', { class: 'chart-legend', html: `<span><i class="sw" style="background:${C_REND}"></i>Self-check</span><span><i class="sw" style="background:${C_FULL}"></i>Reviewer, full feedback</span>` }));
  groupBars($('#mt-c3'), { xmax: 100,
    editors: [{ name: 'GPT-6.1-sol', color: '#2a78d6', muted: '#a9c6ec' }, { name: 'GPT-6-luna', color: '#eb6834', muted: '#f3b89f' }],
    groups: [{ label: 'Single-shot, medium reasoning', v: [64.7, 36.9] }, { label: 'Single-shot, best reasoning effort', v: [74.7, 54.2] },
             { label: 'Coding agent (Codex CLI) that renders and checks its own result', v: [74.7, 34.6] },
             { label: 'Multi-turn with self-review', v: [83.0, 61.5], fb: true }, { label: 'Multi-turn with a separate reviewer', v: [85.6, 65.7], fb: true }] });
  dotRows($('#mt-c4'), { rows: R(Object.keys(MT), ['Qwen3.8-27B']).map(r => ({ ...r, v: [r.v[5], r.v[4]] })), xmax: 90,
    ref: { v: 46.8, label: 'Kimi K3 single-shot 46.8%' }, series: [
      { i: 0, name: 'Self-review (the editor reviews itself)', color: C_SELF }, { i: 1, name: 'Reviewed by GPT-6-luna', color: C_FULL, label: true }] });
  // tabs
  const tabs = [...document.querySelectorAll('.mt-tab')], panels = [...document.querySelectorAll('.mt-panel')];
  const show = k => { tabs.forEach((t, j) => { t.setAttribute('aria-selected', j === k); t.tabIndex = j === k ? 0 : -1; }); panels.forEach((p, j) => p.hidden = j !== k); };
  tabs.forEach((t, j) => t.addEventListener('click', () => show(j)));
  $('#mt-tabs').addEventListener('keydown', e => {
    const cur = tabs.findIndex(t => t.getAttribute('aria-selected') === 'true');
    const n = e.key === 'ArrowRight' ? cur + 1 : e.key === 'ArrowLeft' ? cur - 1 : null;
    if (n == null) return; const j = (n + tabs.length) % tabs.length; show(j); tabs[j].focus();
  });
}

/* ================================================================ misc */
function initCopy() {
  document.querySelectorAll('.copy').forEach(b => b.addEventListener('click', async () => {
    const txt = document.getElementById(b.dataset.copy).innerText;
    try { await navigator.clipboard.writeText(txt); b.textContent = 'Copied'; } catch { b.textContent = 'Select and copy'; }
    setTimeout(() => (b.textContent = 'Copy'), 1500);
  }));
}
function initNav() {
  const links = [...document.querySelectorAll('.toplinks a')];
  const map = new Map(links.map(a => [a.getAttribute('href').slice(1), a]));
  const io = new IntersectionObserver(es => {
    for (const e of es) if (e.isIntersecting) { links.forEach(a => a.classList.remove('active')); map.get(e.target.id)?.classList.add('active'); }
  }, { rootMargin: '-45% 0px -50% 0px' });
  for (const id of map.keys()) { const s = document.getElementById(id); if (s) io.observe(s); }
}
